import socket
# Minimal DNS simulation: answers A queries for lab.redpanda.test with 127.0.0.1.
s=socket.socket(socket.AF_INET,socket.SOCK_DGRAM); s.bind(("127.0.0.1",5353))
while True:
 data,addr=s.recvfrom(2048)
 try:
  i=12; labels=[]
  while data[i]:
   n=data[i]; i+=1; labels.append(data[i:i+n].decode("ascii", "ignore")); i+=n
  i+=1; qtype=int.from_bytes(data[i:i+2],"big"); qclass=int.from_bytes(data[i+2:i+4],"big"); question=data[12:i+4]
  if ".".join(labels)=="lab.redpanda.test" and qtype==1 and qclass==1:
   answer=b"\xc0\x0c\x00\x01\x00\x01\x00\x00\x00\x3c\x00\x04\x7f\x00\x00\x01"; hdr=data[:2]+b"\x81\x80\x00\x01\x00\x01\x00\x00\x00\x00"; s.sendto(hdr+question+answer,addr)
  else: s.sendto(data[:2]+b"\x81\x83"+b"\x00\x01\x00\x00\x00\x00\x00\x00"+data[12:],addr)
 except Exception: pass
